    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.ExportDialogViewModel.BrowseExportPath
    private async Task BrowseExportPathAsync()
    {
        // Win32 SaveFileDialog → StorageProvider save picker (hal: file_pickers), owned by
        // this dialog's window (fallback: main window).
        var owner = FindOwnerWindowForPicker();
        if (owner == null) { return; }

        var file = await owner.StorageProvider.SaveFilePickerAsync(new FilePickerSaveOptions
        {
            DefaultExtension = "csv",
            FileTypeChoices = new[] { new FilePickerFileType("Log File") { Patterns = new[] { "*.csv" } } }
        });

        var path = file?.TryGetLocalPath();
        if (path == null) { return; }

        ExportFilePath = path;
    }

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.ExportDialogViewModel.BrowseExportDirectory
    private async Task BrowseExportDirectoryAsync()
    {
        // WinForms FolderBrowserDialog → StorageProvider folder picker (hal: file_pickers).
        var owner = FindOwnerWindowForPicker();
        if (owner == null) { return; }

        var folders = await owner.StorageProvider.OpenFolderPickerAsync(new FolderPickerOpenOptions
        {
            AllowMultiple = false
        });

        var path = folders.Count > 0 ? folders[0].TryGetLocalPath() : null;
        if (path == null) { return; }

        ExportFilePath = path;
    }

    private Window? FindOwnerWindowForPicker()
    {
        if (Application.Current?.ApplicationLifetime is not IClassicDesktopStyleApplicationLifetime desktop)
        {
            return null;
        }

        return desktop.Windows.FirstOrDefault(w => w.DataContext == this) ?? desktop.MainWindow;
    }

